import os
from datetime import date, timedelta

import requests

BASE_URL = "https://api.socbench.example"
INDUSTRY_ID = os.getenv("INDUSTRY_ID", "industry-1")
TIMEOUT = 30

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def api_get(path, params=None):
    response = session.get(f"{BASE_URL}{path}", params=params, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def api_post(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def api_put(path, payload):
    response = session.put(f"{BASE_URL}{path}", json=payload, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def items_from(data, *possible_keys):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in possible_keys:
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


maintenance_data = api_get("/maintenance-schedule")
maintenance_entries = items_from(
    maintenance_data, "schedule", "maintenanceSchedule", "items", "data"
)

equipment_data = api_get("/equipment-monitoring")
equipment = items_from(
    equipment_data, "equipment", "equipmentDetails", "items", "data"
)

energy_usage = api_get("/energy-usage", params={"industryId": INDUSTRY_ID})

efficiency_results = []
for item in equipment:
    equipment_id = item.get("equipmentId", item.get("id"))
    if equipment_id is None:
        continue

    usage_details = {
        "energyUsage": energy_usage,
        "status": item.get("status"),
        "performanceMetrics": item.get(
            "performanceMetrics", item.get("metrics", {})
        ),
    }
    efficiency_results.append(
        api_post(
            "/equipment-efficiency-check",
            {
                "equipmentId": equipment_id,
                "industryId": INDUSTRY_ID,
                "usageDetails": usage_details,
            },
        )
    )

planned_dates = []
start_date = date.today() + timedelta(days=30)

for index, entry in enumerate(maintenance_entries):
    schedule_id = entry.get("id", entry.get("scheduleId"))
    if schedule_id is None:
        continue

    planned_date = start_date + timedelta(days=7 * index)
    api_put(
        f"/maintenance-schedule/{schedule_id}",
        {"date": planned_date.isoformat()},
    )
    planned_dates.append(
        {
            "scheduleId": schedule_id,
            "facilityId": entry.get("facilityId"),
            "date": planned_date.isoformat(),
        }
    )

today = date.today()
report_feedback = {
    "reviewCriteria": [
        "Each maintenance activity should have an identifiable schedule ID and facility.",
        "Scheduled dates should be valid and not in the past.",
        "Activities should be distributed across facilities to avoid unnecessary scheduling conflicts.",
    ],
    "findings": [],
    "suggestedImprovements": [
        "Include facility and resource identifiers in every schedule entry.",
        "Record maintenance status, responsible party, and completion date.",
        "Prioritize overdue activities and coordinate dates for shared resources.",
    ],
}

seen_dates = {}
for entry in maintenance_entries:
    scheduled = entry.get("date", entry.get("maintenance_date"))
    facility_id = entry.get("facilityId")
    if not scheduled:
        report_feedback["findings"].append(
            f"Schedule entry {entry.get('id', entry.get('scheduleId', 'unknown'))} has no date."
        )
        continue

    try:
        scheduled_date = date.fromisoformat(str(scheduled)[:10])
        if scheduled_date < today:
            report_feedback["findings"].append(
                f"Schedule entry {entry.get('id', entry.get('scheduleId', 'unknown'))} is overdue."
            )
        key = (facility_id, scheduled_date.isoformat())
        if key in seen_dates:
            report_feedback["findings"].append(
                f"Multiple activities are scheduled for facility {facility_id} on {scheduled_date.isoformat()}."
            )
        seen_dates[key] = True
    except ValueError:
        report_feedback["findings"].append(
            f"Schedule entry {entry.get('id', entry.get('scheduleId', 'unknown'))} has an invalid date."
        )

api_post(
    "/recommendation-report",
    {
        "parameters": {
            "maintenanceSchedule": maintenance_data,
            "plannedMaintenanceDates": planned_dates,
            "equipmentEfficiencyEvaluations": efficiency_results,
            "maintenanceReportAccuracyFeedback": report_feedback,
        }
    },
)

