import json
import requests

BASE_URL = "https://api.socbench.example"
FORECAST_PERIOD = "2026 Q4"
SECTORS = ["residential", "commercial", "industrial"]
TIMEOUT = 30

session = requests.Session()
session.headers.update({"Accept": "application/json"})

def get_json(path, params=None):
    response = session.get(
        f"{BASE_URL}{path}",
        params=params,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    try:
        return response.json()
    except ValueError:
        return {"response_text": response.text}

def post_json(path, payload):
    response = session.post(
        f"{BASE_URL}{path}",
        json=payload,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    try:
        return {"status_code": response.status_code, "data": response.json()}
    except ValueError:
        return {"status_code": response.status_code, "data": response.text}

generation_forecast = get_json("/generation/forecast")
usage_forecast = get_json(
    "/forecast-usage",
    params={"forecastPeriod": FORECAST_PERIOD},
)
sector_trends = get_json(
    "/sector-trends",
    params={"sectors": ",".join(SECTORS)},
)
wind_generation = get_json("/generation/wind")
monitored_resources = get_json("/resources/list")

offset_submission = post_json(
    "/offset-projects",
    {
        "project_name": f"Renewable Energy Offset Portfolio - {FORECAST_PERIOD}",
        "project_type": "renewable_energy_offset",
        "description": (
            "Offset carbon emissions associated with forecast energy requirements "
            "across residential, commercial, and industrial sectors."
        ),
        "forecast_period": FORECAST_PERIOD,
        "sectors": SECTORS,
        "generation_forecast": generation_forecast,
        "usage_forecast": usage_forecast,
        "wind_generation": wind_generation,
    },
)

def find_numeric_values(value, keys):
    found = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key in keys and isinstance(item, (int, float)):
                found.append(float(item))
            else:
                found.extend(find_numeric_values(item, keys))
    elif isinstance(value, list):
        for item in value:
            found.extend(find_numeric_values(item, keys))
    return found

forecast_generation_values = find_numeric_values(
    generation_forecast,
    {"solar_forecast_mw", "wind_forecast_mw", "total_generation_forecast_mw"},
)
usage_values = find_numeric_values(
    usage_forecast,
    {"usage_mw", "forecast_usage_mw", "energy_usage_mw", "total_usage_mw"},
)
wind_values = find_numeric_values(wind_generation, {"wind_generation_mw"})

resource_items = (
    monitored_resources
    if isinstance(monitored_resources, list)
    else monitored_resources.get("resources", [])
    if isinstance(monitored_resources, dict)
    else []
)
resource_statuses = [
    {
        "resource_id": item.get("resource_id"),
        "type": item.get("type"),
        "status": item.get("status"),
    }
    for item in resource_items
    if isinstance(item, dict)
]
unavailable_resources = [
    item for item in resource_statuses
    if item.get("status") in {"under_maintenance", "offline", "unavailable"}
]

alignment = {
    "forecast_period": FORECAST_PERIOD,
    "sectors_reviewed": SECTORS,
    "generation_forecast_mw_values": forecast_generation_values,
    "usage_forecast_mw_values": usage_values,
    "current_wind_generation_mw_values": wind_values,
    "generation_covers_usage": (
        sum(forecast_generation_values) >= sum(usage_values)
        if forecast_generation_values and usage_values
        else None
    ),
    "monitored_resource_count": len(resource_statuses),
    "resources_unavailable_or_under_maintenance": unavailable_resources,
    "assessment": (
        "Review the listed unavailable resources against forecast demand; "
        "the API response does not provide enough comparable forecast values "
        "to determine coverage."
        if unavailable_resources or not forecast_generation_values or not usage_values
        else "Compare forecast generation with sector usage and confirm available resources can meet demand."
    ),
}

analysis = {
    "generation_forecast": generation_forecast,
    "usage_forecast": usage_forecast,
