import requests
from urllib.parse import quote

BASE_URL = "https://api.socbench.example"


def material_name(material):
    if isinstance(material, str):
        return material
    for key in ("name", "material", "type", "category"):
        if material.get(key):
            return str(material[key])
    return str(material)


def get_project_materials_and_suggestions(project_id):
    url = f"{BASE_URL}/projects/{quote(str(project_id), safe='')}/materials"
    response = requests.get(url, timeout=30)
    response.raise_for_status()
    materials = response.json()

    results = []
    for material in materials:
        name = material_name(material)
        response = requests.get(
            f"{BASE_URL}/suggestions/material-improvements",
            params={"material": name},
            timeout=30,
        )
        response.raise_for_status()
        data = response.json()
        results.append({
            "material": material,
            "recommendations": data.get("recommendations", []),
        })

    return materials, results


def suggest_recycler(project_id, name, location):
    materials, recommendations = get_project_materials_and_suggestions(project_id)
    accepted_materials = sorted({material_name(material) for material in materials})

    recycler = {
        "name": name,
        "location": location,
        "materials_accepted": accepted_materials,
