def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    return response.json()


def find_records(data):
    """Extract record-like dictionaries from common API response shapes."""
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    if isinstance(data, dict):
        for key in ("equipment", "machinery", "items", "materials", "inventory", "data"):
            value = data.get(key)
            if isinstance(value, list):
                return [item for item in value if isinstance(item, dict)]
        return [data]
    return []


site_response = session.post(f"{BASE_URL}/sites/add", json=SITE)
site_response.raise_for_status()
site_result = site_response.json() if site_response.content else {}

site_id = (
    site_result.get("siteId")
    or site_result.get("id")
    or site_result.get("site", {}).get("id")
)

operational_status = get_json("/equipment-status")
equipment_records = find_records(operational_status)

maintenance_results = []
for equipment in equipment_records:
    status = str(
        equipment.get("status")
        or equipment.get("operationalStatus")
        or ""
    ).lower()
    if status not in {"operational", "active", "running", "online"}:
        continue

    equipment_id = (
        equipment.get("equipmentId")
        or equipment.get("id")
        or equipment.get("equipment_id")
    )
    if equipment_id is None:
