import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

# Supply the categories and quantities required for this procurement.
product_categories = []
required_materials = []  # Example: [{"material_id": "123", "quantity": 50}]

session = requests.Session()
session.headers.update({"Accept": "application/json"})

trends_response = session.get(f"{BASE_URL}/market-trends", timeout=TIMEOUT)
trends_response.raise_for_status()
market_trends = trends_response.json()

categories_response = session.get(f"{BASE_URL}/materials/categories", timeout=TIMEOUT)
categories_response.raise_for_status()
all_categories = categories_response.json()

materials_response = session.get(f"{BASE_URL}/materials", timeout=TIMEOUT)
materials_response.raise_for_status()
materials = materials_response.json()

inventory_response = session.get(f"{BASE_URL}/inventory/status", timeout=TIMEOUT)
inventory_response.raise_for_status()
inventory = inventory_response.json()

# If no categories were specified, use the categories returned by the API.
if not product_categories:
    if isinstance(all_categories, list):
        product_categories = all_categories
    elif isinstance(all_categories, dict):
        product_categories = all_categories.get("categories", [])

def category_name(category):
    if isinstance(category, dict):
        return category.get("name") or category.get("category") or category.get("id")
    return str(category)

requested_category_names = {
    category_name(category).casefold()
    for category in product_categories
    if category_name(category)
}

if isinstance(materials, dict):
    material_list = materials.get("materials", [])
else:
    material_list = materials if isinstance(materials, list) else []

materials_in_scope = [
    material
    for material in material_list
    if not requested_category_names
    or str(material.get("category", "")).casefold() in requested_category_names
]

# The trends endpoint does not document category query parameters, so retain its
# full response and the locally identified categories/materials for review.
market_analysis = {
    "trends": market_trends,
    "categories": product_categories,
