        timeout=TIMEOUT,
    )
    procurement_response.raise_for_status()
    procurement_result = procurement_response.json() if procurement_response.content else {}

    material_ids = {
        str(item["material_id"])
        for item in required_materials
        if isinstance(item, dict) and item.get("material_id") is not None
    }

    if isinstance(procurement_result, dict):
        response_materials = procurement_result.get("materials", [])
        if isinstance(response_materials, list):
            material_ids.update(
                str(item["id"])
                for item in response_materials
                if isinstance(item, dict) and item.get("id") is not None
            )

    for material_id in sorted(material_ids):
        compliance_response = session.get(
            f"{BASE_URL}/materials/{material_id}/compliance",
