if isinstance(inventory, dict):
    inventory_items = inventory.get("inventory", [])
else:
    inventory_items = inventory if isinstance(inventory, list) else []

outdated_materials = [
    item
    for item in inventory_items
    if isinstance(item, dict)
    and (
        item.get("outdated") is True
        or str(item.get("status", "")).casefold() in {"outdated", "expired", "obsolete"}
    )
]

# No material-removal endpoint is documented, so outdated materials can be
# identified here but cannot be removed through the documented API.

result = {
    "market_analysis": market_analysis,
    "procurement_result": procurement_result,
    "compliance_results": compliance_results,
