import datetime
import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def put_json(path, payload):
    response = session.put(f"{BASE_URL}{path}", json=payload, timeout=30)
    response.raise_for_status()
    return response.json() if response.content else None


def find_materials(data):
    if isinstance(data, list):
        return data
    if not isinstance(data, dict):
        return []

    for key in ("materials", "items", "inventory", "records"):
        value = data.get(key)
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            found = find_materials(value)
            if found:
                return found

    return []


inventory_report = get_json("/inventory/status")
materials = find_materials(inventory_report)

results = []
for material in materials:
    if not isinstance(material, dict):
        continue

    material_name = (
        material.get("materialName")
        or material.get("name")
        or material.get("material")
    )
    if not material_name:
        continue

    classification_result = post_json(
        "/materials/classify",
        {"materialName": material_name},
    )

    classification_text = str(
        classification_result.get("classification", "")
    ).lower()
    compliance_required = bool(
        material.get("complianceRequired")
        or material.get("requiresCompliance")
        or "compliance" in classification_text
    )

    compliance_result = None
    material_id = material.get("id") or material.get("materialId")
    if compliance_required and material_id is not None:
        compliance_result = get_json(
            f"/materials/{material_id}/compliance"
        )

    compliance_text = str(compliance_result or "").lower()
    if compliance_required and any(
        word in compliance_text for word in ("fail", "non-compliant", "noncompliant")
    ):
        shipment_route = "hold_for_compliance"
    elif any(word in classification_text for word in ("recyclable", "recyclable")):
        shipment_route = "recycling"
    else:
        shipment_route = "review"

    if material_id is not None:
        put_json(
            f"/materials/{material_id}",
            {"shipmentRoute": shipment_route},
        )

    results.append(
        {
            "material": material_name,
            "quantity": material.get("quantity"),
            "classification": classification_result,
            "compliance": compliance_result,
            "shipmentRoute": shipment_route,
        }
    )

start_date = (datetime.date.today() - datetime.timedelta(days=30)).isoformat()
classification_statistics = get_json(
    "/analysis/statistics",
    params={"startDate": start_date},
)

# The documented API has no machinery-maintenance scheduling endpoint and no
# resource-usage statistics endpoint. The available statistics endpoint reports
# material classification statistics only.
print(
    {
        "inventory": inventory_report,
        "materialResults": results,
        "classificationStatistics": classification_statistics,
        "maintenanceScheduling": "Unavailable: no documented endpoint.",
        "resourceUsageStatistics": "Unavailable: no documented endpoint.",
    }
)

