import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30


def get_json(url):
    response = requests.get(url, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def find_records(data, keys):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in keys:
            value = data.get(key)
            if isinstance(value, list):
                return value
        for value in data.values():
            result = find_records(value, keys)
            if result:
                return result
    return []


def find_id(data, preferred_keys):
    if isinstance(data, dict):
        for key in preferred_keys:
            if data.get(key) is not None:
                return data[key]
        for value in data.values():
            result = find_id(value, preferred_keys)
            if result is not None:
                return result
    elif isinstance(data, list):
        for value in data:
            result = find_id(value, preferred_keys)
            if result is not None:
                return result
    return None


# Create several orders in one request; the endpoint documents an array request body.
orders_to_create = [
    {
        "items": [{"name": "Industrial bearings", "quantity": 25}],
        "status": "pending",
    },
    {
        "items": [{"name": "Steel fasteners", "quantity": 100}],
        "status": "pending",
    },
