        "items": [{"name": "Hydraulic hoses", "quantity": 10}],
        "status": "pending",
    },
]

response = requests.post(
    f"{BASE_URL}/orders",
    json=orders_to_create,
    timeout=TIMEOUT,
)
response.raise_for_status()
created_orders = response.json() if response.content else []

# Retrieve the summary of all orders after creating the new ones.
all_orders = get_json(f"{BASE_URL}/orders")

# Fetch a detailed record for one of the newly created orders when its ID is returned.
order_id = find_id(created_orders, ("order_id", "id"))
if order_id is None:
    order_records = find_records(all_orders, ("orders", "data", "results"))
    if order_records:
        order_id = find_id(order_records[0], ("order_id", "id"))

order_details = None
if order_id is not None:
    order_details = get_json(f"{BASE_URL}/orders/{order_id}")

# Review upcoming maintenance schedules and create a local resource plan.
maintenance_data = get_json(f"{BASE_URL}/maintenance_schedule")
maintenance_records = find_records(
