    item_id = item.get("itemId", item.get("id"))
    quantity = item.get("quantity")
    if item_id is not None and isinstance(quantity, (int, float)):
        stock_by_id[str(item_id)] = quantity
        forecast_input.append({"itemId": str(item_id), "quantity": quantity})

