    found = set()

    def walk(item):
        if isinstance(item, dict):
            for key, child in item.items():
                normalized = key.lower().replace("-", "_")
                if normalized in accepted_keys and isinstance(child, (str, int)):
                    found.add(str(child))
                elif normalized in accepted_keys and isinstance(child, list):
                    found.update(str(entry) for entry in child if isinstance(entry, (str, int)))
                walk(child)
        elif isinstance(item, list):
            for child in item:
                walk(child)

    walk(value)
    return found


