BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=30)
    response.raise_for_status()
    return response.json()


def as_list(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("patients", "items", "inventory", "alerts", "results", "data"):
            if isinstance(data.get(key), list):
                return data[key]
    return []


def normalize(value):
    return re.sub(r"\s+", " ", str(value or "")).strip().casefold()


def get_patient_id(patient):
    if isinstance(patient, dict):
        return patient.get("id") or patient.get("patient_id")
    return None


def collect_supply_needs(data):
    needs = []

    def add_entry(entry, default_quantity=1):
        if isinstance(entry, str):
            name = entry.strip()
            if name:
                needs.append((name, default_quantity))
        elif isinstance(entry, dict):
            item = (
                entry.get("item_id")
                or entry.get("supply_id")
                or entry.get("item_name")
                or entry.get("supply_name")
                or entry.get("name")
                or entry.get("medication_name")
            )
            quantity = entry.get("quantity", entry.get("count", entry.get("needed", default_quantity)))
            try:
                quantity = max(1, int(quantity))
            except (TypeError, ValueError):
                quantity = default_quantity
            if item:
                needs.append((str(item), quantity))
            else:
                walk(entry)

    def walk(value):
        if isinstance(value, dict):
            for key, child in value.items():
                key_normalized = normalize(key)
                if any(term in key_normalized for term in (
                    "required_suppl", "needed_suppl", "medical_suppl",
                    "supply_needs", "supplies_required", "required_items",
                    "needed_items",
                )):
                    if isinstance(child, list):
                        for entry in child:
                            add_entry(entry)
                    elif isinstance(child, dict):
                        add_entry(child)
                    elif isinstance(child, str):
                        add_entry(child)
                else:
                    walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(data)
    return needs


patients = as_list(get_json("/patients"))
inventory = as_list(get_json("/inventory"))

patient_needs = {}
for patient in patients:
    patient_id = get_patient_id(patient)
    if not patient_id:
        continue
    records = get_json(f"/patients/{patient_id}/records")
    patient_needs[patient_id] = collect_supply_needs(records)

demand = {}
