import json
import os
import re
import requests

BASE_URL = "https://api.socbench.example"
HEADERS = {"Accept": "application/json"}
if os.getenv("SOCBENCH_API_TOKEN"):
    HEADERS["Authorization"] = f"Bearer {os.environ['SOCBENCH_API_TOKEN']}"


def get_json(path):
    response = requests.get(
        f"{BASE_URL}{path}",
        headers=HEADERS,
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def records(payload):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        for key in ("items", "data", "results", "equipment", "threats", "assets", "systems"):
            value = payload.get(key)
            if isinstance(value, list):
                return value
    return []


def text_of(value):
    return json.dumps(value, ensure_ascii=False, default=str).lower()


def equipment_identifiers(item):
    identifiers = set()
    if isinstance(item, dict):
        for key, value in item.items():
            if value is not None and any(term in key.lower() for term in ("id", "name", "hostname", "asset", "serial")):
                identifiers.add(str(value).strip().lower())
    return {value for value in identifiers if len(value) > 2}


