threats = records(get_json("/threats"))
tracking_payload = get_json("/tracking/assets")
tracking = records(tracking_payload)
systems = records(get_json("/systems"))

equipment_risks = []
for item in equipment:
    identifiers = equipment_identifiers(item)
    related_threats = [
        threat for threat in threats
        if any(identifier in text_of(threat) for identifier in identifiers)
    ]
    if related_threats:
        equipment_risks.append({
            "equipment": item,
            "related_threats": related_threats,
            "potentially_susceptible": True,
        })

tracking_text = text_of(tracking_payload)
