tracking_anomalies = [
    item for item in tracking
    if any(term in text_of(item) for term in anomaly_terms)
]

report = {
    "equipment_count": len(equipment),
    "threat_count": len(threats),
    "equipment_with_matching_threats": equipment_risks,
    "unmatched_threats": [
