def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def numeric_value(record, keys):
    for key in keys:
        value = record.get(key)
        if isinstance(value, (int, float)):
            return float(value)
    return None


def find_zone_records(data):
    records = []

    def walk(value):
        if isinstance(value, dict):
            zone_id = value.get("zone_id", value.get("id"))
            demand = numeric_value(
                value,
                ("demand", "electricity_demand", "current_demand", "load", "consumption"),
            )
            if zone_id is not None and demand is not None:
                records.append({"zone_id": str(zone_id), "demand": demand})
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(data)

    unique = {}
    for record in records:
        unique[record["zone_id"]] = record
    return list(unique.values())


def forecast_value_for_zone(forecast, zone_id):
    if isinstance(forecast, dict):
        for key in ("zones", "forecasts", "patterns", "data"):
            nested = forecast.get(key)
            result = forecast_value_for_zone(nested, zone_id)
            if result is not None:
                return result
        if str(forecast.get("zone_id", forecast.get("id", ""))) == zone_id:
            return numeric_value(
                forecast,
                ("forecast_demand", "predicted_demand", "demand", "consumption", "load"),
            )
        for value in forecast.values():
            result = forecast_value_for_zone(value, zone_id)
            if result is not None:
                return result
    elif isinstance(forecast, list):
        for item in forecast:
            result = forecast_value_for_zone(item, zone_id)
            if result is not None:
                return result
    return None


demand_data = get_json("/realtime-demand")
forecast_data = get_json("/forecast-patterns")
zones = find_zone_records(demand_data)

if zones:
    ordered_demands = sorted(zone["demand"] for zone in zones)
    high_demand_cutoff = ordered_demands[max(0, int(0.75 * (len(ordered_demands) - 1)))]
    high_demand_zones = [
        zone for zone in zones if zone["demand"] >= high_demand_cutoff
    ]
else:
    high_demand_zones = []

allocation_payload = {
    "priority": "high",
    "zones": [
        {
            "zone_id": zone["zone_id"],
            "current_demand": zone["demand"],
            "forecast_demand": forecast_value_for_zone(
                forecast_data, zone["zone_id"]
            ),
        }
        for zone in high_demand_zones
    ],
    "real_time_demand": demand_data,
    "forecast": forecast_data,
}

allocation_response = session.post(
    f"{BASE_URL}/allocate-resources",
    json=allocation_payload,
    timeout=TIMEOUT,
)
allocation_response.raise_for_status()

threshold_updates = []
for zone in zones:
    forecast_demand = forecast_value_for_zone(forecast_data, zone["zone_id"])
    reference_demand = max(zone["demand"], forecast_demand or 0)
    threshold = reference_demand * 1.15

    response = session.patch(
        f"{BASE_URL}/update-thresholds",
        json={"zone_id": zone["zone_id"], "threshold": threshold},
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    threshold_updates.append(
        {"zone_id": zone["zone_id"], "threshold": threshold}
    )

suggestions = []
for zone in high_demand_zones:
    forecast_demand = forecast_value_for_zone(forecast_data, zone["zone_id"])
    trend = (
        "forecast demand is higher than current demand"
        if forecast_demand is not None and forecast_demand > zone["demand"]
        else "prioritize peak-load management and flexible consumption"
    )
    suggestions.append(
