                f"periods, and improve efficiency; {trend}."
            ),
        }
    )

try:
    override_response = session.delete(
        f"{BASE_URL}/override-settings",
        timeout=TIMEOUT,
    )
    override_response.raise_for_status()
    overrides_reset = True
finally:
