down_payment_details = get_json(
    "/down-payment-summary",
    params={"location": property_criteria["location"], "propertyType": "residential"},
)

interest_rate_data = get_json("/interest-rates")
rates = collect_rates(interest_rate_data)
rates.extend([assumed_interest_rate - 0.5, assumed_interest_rate, assumed_interest_rate + 0.5])
rates = sorted({round(rate, 4) for rate in rates if rate > 0})

payment_scenarios = []
for rate in rates:
    payment = post_json(
        "/calculate-payment",
        {
            "principal": loan_amount,
            "interestRate": rate,
            "loanTerm": loan_term_years,
        },
    )
    payment_scenarios.append({"interestRate": rate, "result": payment})

results = {
    "recommended_agents": recommended_agents,
    "search_criteria_to_save": search_criteria_to_save,
    "existing_saved_searches": saved_searches,
    "down_payment_details": down_payment_details,
    "interest_rate_data": interest_rate_data,
    "payment_scenarios": payment_scenarios,
}
